from pathlib import Path
root=Path(__file__).parent/'source'
p=root/'go2_him/moe_stair_env.py';s=p.read_text()
def rep(a,b):
 global s
 assert a in s,a[:100]
 s=s.replace(a,b)
rep('from go2_him.hard_joint_limits import HardJointLimits, position_constraint_contract','from go2_him.hard_joint_limits import HardJointLimits, position_constraint_contract\nfrom go2_him.sim2real_dr import DomainRandomization')
rep("position_constraint='hard', target_mode='auto'):","position_constraint='hard', target_mode='auto', domain_randomization=False):")
rep('self.rng = np.random.default_rng(seed)','self.seed=seed\n        self.rng = np.random.default_rng(seed)')
rep("robot_xml=original.UPSTREAM/'RoboGauge/resources/robots/go2/go2.xml'","robot_xml=ROOT/'assets/unitree_go2/go2.xml'")
rep('self.stop_phase = False\n        self.reset()', 'self.stop_phase = False\n        self.dr = DomainRandomization(self, enabled=domain_randomization)\n        self.reset()')
rep('mj.mj_resetData(m,d)\n        d.qpos[:] = self.initial_qpos','mj.mj_resetData(m,d)\n        self.dr.reset()\n        d.qpos[:] = self.initial_qpos')
rep('self.elapsed=0.; self.episode_return=0.; self.roll_sq=0.; self.control_samples=0','self.elapsed=0.; self.episode_return=0.; self.roll_sq=0.; self.control_samples=0\n        self.tracking_sum=0.;self.tracking_steps=0')
rep('values=self.raw_observation()', 'values=self.dr.noisy_observation(self.raw_observation())')
rep('self.target_commands.record(raw_target,target,self.profile.lower,self.profile.upper)', 'command_target=target.copy()\n        if self.dr.enabled:\n            target=self.dr.actuator_target(command_target)\n        self.target_commands.record(raw_target,target,self.profile.lower,self.profile.upper)')
rep('applied=np.clip(requested,-e.physical_effort,e.physical_effort)', 'applied=np.clip(requested*self.dr.strength,-e.physical_effort,e.physical_effort)\n            self.dr.apply_push()')
rep("bodyvel=rot.T@d.qvel[:3]\n        state=", "bodyvel=rot.T@d.qvel[:3]\n        if command_before>0:\n            self.tracking_sum+=float(np.exp(-np.sum((bodyvel[:2]-[command_before,0.])**2)/.25))\n            self.tracking_steps+=1\n        state=")
rep("'external_stop_command':True}","'external_stop_command':True,'domain_randomization':self.dr.summary(),\n                'tracking_score':self.tracking_sum/max(1,self.tracking_steps)}")
rep("obs=self.reset()\n        return obs,reward,status is not None,info", "obs=self.reset()\n        info['critic_observation']=self.dr.privileged(obs)\n        return obs,reward,status is not None,info")
rep("def env_worker(conn, seed, count, stair_steps=2, position_constraint='hard'):","def env_worker(conn, seed, count, stair_steps=2, position_constraint='hard', domain_randomization=False):")
rep("position_constraint=position_constraint) for i in range(count)]", "position_constraint=position_constraint, domain_randomization=domain_randomization) for i in range(count)]")
rep("conn.send(np.stack([e.observation(append=False) for e in envs]))", "initial=np.stack([e.observation(append=False) for e in envs])\n    conn.send((initial,np.stack([e.dr.privileged(o) for e,o in zip(envs,initial)])))")
rep("e.target_mode=payload.get('target_mode','auto')", "e.target_mode=payload.get('target_mode','auto')\n                    e.dr.level=payload.get('dr_level',.15)")
p.write_text(s)
p=root/'scripts/train_moe_stairs.py';s=p.read_text()
rep('from go2_him.target_clip import TARGET_CLIP_CONFIG, TargetClipAccumulator','from go2_him.target_clip import TARGET_CLIP_CONFIG, TargetClipAccumulator\nfrom go2_him.sim2real_dr import CONFIG as DR_CONFIG, Curriculum, PRIVILEGED_EXTRA')
rep("def __init__(self,n,workers,seed,stair_steps=2,position_constraint='hard'):","def __init__(self,n,workers,seed,stair_steps=2,position_constraint='hard',domain_randomization=False):")
rep('args=(child,seed+i*self.count,self.count,stair_steps,position_constraint)', 'args=(child,seed+i*self.count,self.count,stair_steps,position_constraint,domain_randomization)')
rep('self.obs=np.concatenate([self.recv(p) for p in self.pipes])', 'initial=[self.recv(p) for p in self.pipes]\n        self.obs=np.concatenate([v[0] for v in initial])\n        self.critic_obs=np.concatenate([v[1] for v in initial])')
rep("'target_mode':getattr(self,'target_mode','auto')", "'target_mode':getattr(self,'target_mode','auto'),\n                                              'dr_level':getattr(self,'dr_level',.15)")
rep('out=[self.recv(p) for p in self.pipes]', "out=[self.recv(p) for p in self.pipes]\n        self.critic_obs=np.stack([info['critic_observation'] for row in out for info in row[3]])\n        for row in out:\n            for info in row[3]:info.pop('critic_observation')")
rep('nn.Linear(225,512)', "nn.Linear(225+(PRIVILEGED_EXTRA if getattr(args,'domain_randomization',False) else 0),512)")
rep("'external_platform_stop':True,'real_robot_driven':False,", "'external_platform_stop':True,'real_robot_driven':False,\n         'domain_randomization':DR_CONFIG if args.domain_randomization else None,\n         'critic_input_size':225+PRIVILEGED_EXTRA if args.domain_randomization else 225,\n         'robot_model':{'source':'Unitree official MJCF','variant':'Go2 EDU, no extra payload',\n            'path':str(ROOT/'assets/unitree_go2/go2.xml'),\n            'sha256':hashlib.sha256((ROOT/'assets/unitree_go2/go2.xml').read_bytes()).hexdigest(),\n            'calibrated_edu_specific_model':False},")
rep("sources.append('go2_him/hard_joint_limits.py')", "sources.extend(['go2_him/hard_joint_limits.py','go2_him/sim2real_dr.py'])")
rep('position_constraint=position_constraint)\n        vec.guard_objective', 'position_constraint=position_constraint,domain_randomization=args.domain_randomization)\n        vec.guard_objective')
rep('obs=torch.as_tensor(vec.obs,device=device)', "obs=torch.as_tensor(vec.obs,device=device)\n        critic_obs=torch.as_tensor(vec.critic_obs,device=device) if args.domain_randomization else obs\n        curriculum=Curriculum()")
rep('vec.settings(frontier,ramp)', 'vec.dr_level=curriculum.level\n            vec.settings(frontier,ramp)')
rep("('obs','actions','logp','values','rewards','dones','mean')", "('obs','critic_obs','actions','logp','values','rewards','dones','mean')")
rep('value=critic(obs).squeeze(-1)', 'value=critic(critic_obs).squeeze(-1)')
rep("(('obs',obs),('actions',action)", "(('obs',obs),('critic_obs',critic_obs),('actions',action)")
rep('obs=torch.as_tensor(next_obs,device=device)', 'obs=torch.as_tensor(next_obs,device=device)\n                critic_obs=torch.as_tensor(vec.critic_obs,device=device) if args.domain_randomization else obs')
rep('critic(obs).squeeze(-1))', 'critic(critic_obs).squeeze(-1))')
rep("critic(flat_obs[idx]).squeeze(-1)", "critic(flat['critic_obs'][idx]).squeeze(-1)")
rep("record={'update':update", "if args.domain_randomization:curriculum.update(episodes,frontier)\n            record={'update':update,'dr_curriculum':curriculum.summary() if args.domain_randomization else None")
rep("'target_mode':job['target_mode'],", "'target_mode':job['target_mode'],\n                            'domain_randomization':job['domain_randomization'],'critic_input_size':job['critic_input_size'],\n                            'robot_model':job['robot_model'],")
rep("p.add_argument('--device',default='cuda:0');train(p.parse_args())", "p.add_argument('--domain-randomization',action='store_true')\n    p.add_argument('--device',default='cuda:0');args=p.parse_args()\n    if args.domain_randomization and args.resume_training:p.error('Asymmetric critic requires a fresh optimizer/critic')\n    train(args)")
p.write_text(s)
